{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT date_trunc('minute', time) m, count(*) n, min(time) first_t, max(time) last_t FROM abnormal_logs WHERE service_name='ts-route-plan-service' AND message LIKE '%ts-travel2-service%' AND message LIKE '%Connection refused%' GROUP BY 1 ORDER BY 1",
          "claim": "ts-route-plan-service logged 74 'Connection refused' errors calling ts-travel2-service, between 14:29:44 and 14:30:32."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) m, count(*) AS rp_post, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) rp_post_err, sum(CASE WHEN service_name='ts-travel2-service' AND attr_span_kind='Server' THEN 1 ELSE 0 END) t2_server FROM abnormal_traces WHERE (service_name='ts-route-plan-service' AND span_name='POST' AND attr_span_kind='Client') OR service_name='ts-travel2-service' GROUP BY 1 ORDER BY 1",
          "claim": "Travel2 server spans vanish in the first minute while route-plan's POST calls fail; both recover by 14:31 with no further errors."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_k8s_pod_name, min(time) first_t, max(time) last_t, count(*) n FROM normal_traces WHERE service_name='ts-travel2-service' GROUP BY 1,2 UNION ALL SELECT service_name, attr_k8s_pod_name, min(time), max(time), count(*) FROM abnormal_traces WHERE service_name='ts-travel2-service' GROUP BY 1,2",
          "claim": "Travel2 emits no spans from 14:29:40 to 14:30:27 in the abnormal window, then resumes on the same pod; the gap is a brief outage."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) m, count(*) AS rp_post, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) rp_post_err FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND span_name='POST' AND attr_span_kind='Client' GROUP BY 1 ORDER BY 1",
          "claim": "Route-plan's outgoing POST calls (to travel2 and travel) error out in the same first two minutes as the travel2 outage."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code sc, count(*) n FROM abnormal_traces WHERE service_name IN ('ts-route-plan-service','ts-travel-plan-service') AND attr_span_kind='Server' AND attr_http_response_status_code=500 GROUP BY 1,2,3,4",
          "claim": "Route-plan returns 500 on routePlan endpoints, and travel-plan's matching calls to route-plan return 500 with 74 errors."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code sc, count(*) n FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' AND attr_http_response_status_code=500 GROUP BY 1,2,3",
          "claim": "Travel-plan's minStation, cheapest and quickest endpoints return 500 for 74 requests, which ui-dashboard then passes to users."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, count(*) n FROM abnormal_logs WHERE service_name='ts-ui-dashboard' AND level='ERROR' AND message LIKE '%travelplanservice%' GROUP BY 1",
          "claim": "ts-ui-dashboard logs ERROR-level access entries with status 500 on travelPlan endpoints, reaching the user."
        }
      ]
    }
  ]
}

